# coding: utf-8
"""044 human-facing reader for published research dossiers, scoped to one project."""
import html,json,urllib.parse
import project_pipeline as pp
import research_workflow as rw
import project_ownership as own
MODULE_ENTITIES=[['project','award','organization','person'],['problem','technology'],['innovation'],['metric','validation'],['patent','paper','achievement'],['event','story'],['application'],['source','task']]
CSS='''body{margin:0;background:#f5f6fa;color:#25273c;font:15px/1.8 system-ui,-apple-system,"PingFang SC",sans-serif}a{color:#5845ce}.research-reader{display:grid;grid-template-columns:210px minmax(0,900px);gap:32px;max-width:1200px;margin:30px auto;padding:0 24px}.research-toc{position:sticky;top:24px;align-self:start}.research-toc a{display:block;text-decoration:none;padding:8px 12px;border-radius:8px;color:#60687b}.research-toc a:hover{background:#ebe8ff}.research-main{min-width:0}.research-main h1{font-size:29px;line-height:1.4}.research-main h2{font-size:21px}.research-tabs{display:flex;gap:8px;margin:20px 0;flex-wrap:wrap}.research-tabs button{border:1px solid #e0e2ec;background:#fff;border-radius:10px;padding:11px 18px;color:#60687b;cursor:pointer;font:inherit}.research-tabs button[aria-pressed=true]{background:#eeeaff;border-color:#8071ef;color:#5845ce}.research-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.research-stats div,.research-box{padding:20px;background:#fff;border:1px solid #e2e4ee;border-radius:14px;margin-bottom:14px}.research-stats b{display:block;font-size:25px}.research-stats span,.research-note{color:#687083;font-size:13px}.research-box summary{cursor:pointer;font-weight:600}.research-box>summary{font-size:18px}.research-box summary small{display:block;font-size:12px;font-weight:400;color:#687083}.research-record{border-top:1px solid #eee;margin-top:18px;padding-top:8px}.research-record dl{margin:0}.research-row{display:grid;grid-template-columns:140px minmax(0,1fr);gap:18px;padding:12px 0;border-top:1px solid #edf0f5}.research-row dt{color:#687083}.research-row dd{margin:0;overflow-wrap:anywhere}.research-row details{font-size:12px;margin-top:8px}.research-row blockquote{margin:8px 0;padding:8px 12px;background:#f6f7fb;white-space:pre-wrap}.research-tag{display:inline-block;font-size:11px;padding:2px 8px;border-radius:5px;background:#eeeaff;color:#5845ce}.research-ai{border-left:3px solid #a691ef;padding-left:14px;margin-top:16px}.research-box p{overflow-wrap:anywhere}[hidden]{display:none!important}@media(max-width:750px){.research-reader{display:block;padding:0 16px;margin:20px auto}.research-toc{position:static;display:flex;gap:4px;overflow:auto;white-space:nowrap;margin-bottom:20px}.research-stats{grid-template-columns:repeat(2,1fr)}.research-row{grid-template-columns:1fr;gap:4px}.research-box{padding:16px}.research-main h1{font-size:24px}}@media print{.research-reader{display:block}.research-toc,.research-tabs{display:none}.research-box{break-inside:avoid}section[hidden]{display:block!important}}'''
def render(lib,pid,header,shared_css):
 p=pp.project(lib,pid);meta=pp.state(p)['project'];w=rw.current(p)
 if not w['revision']:return None
 revision='research-%06d'%w['revision'];data=rw.dataset(p,w);fields=rw.schema();records=data['records'];interpretations=data.get('interpretations',[])
 sources=own.select(p,pp.state(p)['sources']);mapping=pp.load(p/'资料关联.json').get('source_titles',{})if(p/'资料关联.json').exists()else{}
 h=html.escape
 def url(path,**values):return path+'?'+urllib.parse.urlencode(dict(project=pid,**values))
 def val(value):return '、'.join(str(x)for x in value)if isinstance(value,list)else json.dumps(value,ensure_ascii=False)if isinstance(value,dict)else str(value)
 def known(r):return [(k,c)for k,c in r.get('cells',{}).items()if c.get('value_state')=='known'and c.get('value')is not None]
 def evidence(c):
  e=c.get('evidence',c);sid=e.get('source_id');quote=e.get('quote');locator=c.get('locator',e.get('locator',''))
  if not sid:return ''
  return '<details><summary>查看出处与原文</summary><p>'+h(locator)+' · <a href="#source-'+h(sid)+'">资料索引</a></p><blockquote>'+h(quote or'原文见对应资料')+'</blockquote></details>'
 def record(r):
  rows=''.join('<div class="research-row"><dt>'+h(fields.get(r['entity'],{}).get(k,{}).get('label',k))+'</dt><dd>'+h(val(c['value']))+evidence(c)+'</dd></div>'for k,c in known(r))
  empty=len(r.get('cells',{}))-len(known(r))
  return '<article class="research-record"><h3>'+h(r['title'])+'</h3><dl>'+rows+'</dl><p class="research-note">'+str(empty)+' 项字段尚未补齐；未用推断填充事实。</p></article>'
 total=sum(len(r.get('cells',{}))for r in records);filled=sum(len(known(r))for r in records)
 module_html=[];assessment=[]
 for i,(name,entities)in enumerate(zip(pp.MODULES,MODULE_ENTITIES),1):
  group=[r for r in records if r['entity']in entities];ai=[x for x in interpretations if x['entity']in entities];n=sum(len(known(r))for r in group);alln=sum(len(r.get('cells',{}))for r in group)
  text=''.join(record(r)for r in group)
  if not group:text='<p class="research-note">暂无已入档事实，继续补充一手材料。</p>'
  for c in ai:text+='<article class="research-ai"><span class="research-tag">AI解读 · 未经工程验证</span><h3>'+h(c['title'])+'</h3><p>'+h(val(c['value']))+'</p><p>适用前提：'+h(c['conditions'])+'</p><p>限制：'+h(c['limitations'])+'</p>'+evidence(c)+'</article>'
  module_html.append('<details class="research-box" id="module-'+str(i)+'"><summary>'+str(i).zfill(2)+' '+h(name)+'<small>'+str(len(group))+' 条事实记录 · '+str(n)+' 个有值字段 · '+str(len(ai))+' 条AI解读</small></summary>'+text+'</details>')
  assessment.append('<li>'+h(name)+'：'+str(n)+' / '+str(alln)+' 个已登记字段有值；'+('待补充记录'if not group else'仍需专业审核')+'</li>')
 source_html=[]
 for sid,x in sources.items():
  origin=x.get('origin',{});u=origin.get('url')or'';title=mapping.get(u)or origin.get('filename')or x['title']
  source_html.append('<article class="research-box" id="source-'+h(sid)+'"><h3>'+h(title)+'</h3><p><a href="'+h(url('/asset',source=sid,kind='original'))+'">下载保存的原件</a> · <a href="'+h(url('/asset',source=sid,kind='document'))+'">查看可读来源</a></p><p class="research-note">'+h(sid)+' · '+h(x['read_scope'])+' · '+h(x['status'])+'</p>'+('<p><a href="'+h(u)+'" rel="noreferrer" target="_blank">原始网站 ↗</a></p>'if u.startswith(('https://','http://'))else'')+'</article>')
 toc='<aside class="research-toc" aria-label="阅读目录"><a href="#overview">档案概览</a>'+''.join('<a href="#module-'+str(i)+'" data-open-module="'+str(i)+'">'+str(i).zfill(2)+' '+h(n)+'</a>'for i,n in enumerate(pp.MODULES,1))+'<a href="#source-list" data-switch="library">资料与解读</a><a href="#quality" data-switch="assessment">档案评估</a></aside>'
 script='''const panels=[...document.querySelectorAll('[data-panel]')];function show(name){panels.forEach(x=>x.hidden=x.dataset.panel!==name);document.querySelectorAll('[data-reader-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.readerTab===name)));}document.querySelectorAll('[data-reader-tab]').forEach(b=>b.onclick=()=>show(b.dataset.readerTab));document.querySelectorAll('[data-open-module]').forEach(a=>a.onclick=()=>{show('archive');document.getElementById('module-'+a.dataset.openModule).open=true;});document.querySelectorAll('[data-switch]').forEach(a=>a.onclick=()=>show(a.dataset.switch));document.querySelectorAll('a[href^="#source-"]').forEach(a=>a.onclick=()=>show('library'));window.addEventListener('beforeprint',()=>{document.querySelectorAll('.research-box').forEach(x=>{x.dataset.printOpen=String(x.open);if(x.tagName==='DETAILS')x.open=true;});});window.addEventListener('afterprint',()=>{document.querySelectorAll('details.research-box').forEach(x=>x.open=x.dataset.printOpen==='true');});show('archive');'''
 return '<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+h(meta['name'])+' · 项目档案</title><style>'+shared_css+CSS+'</style>'+header+'<div class="research-reader">'+toc+'<main class="research-main" id="workspace-content"><header id="overview"><p class="research-note">研究整理版 · '+h(revision)+' · 非项目方或专家审核结论</p><h1>'+h(meta['name'])+'</h1><p>持续整合原始材料、事实与设计解读。未知信息保留空白，AI分析单独展示。</p></header><div class="research-stats"><div><b>'+str(len(records))+'</b><span>结构化记录</span></div><div><b>'+str(filled)+'</b><span>有值字段</span></div><div><b>'+str(len(sources))+'</b><span>已保存资料</span></div><div><b>'+str(len(interpretations))+'</b><span>AI解读</span></div></div><nav class="research-tabs" aria-label="档案视图"><button data-reader-tab="archive">项目档案</button><button data-reader-tab="library">资料与解读</button><button data-reader-tab="assessment">档案评估</button></nav><section data-panel="archive">'+''.join(module_html)+'</section><section data-panel="library" id="source-list"><h2>资料与解读</h2><p class="research-note">原件保存不等于全文已核读；资料状态与结论审核分别记录。AI解读列于对应档案模块。</p>'+''.join(source_html)+'</section><section data-panel="assessment" id="quality"><h2>档案评估</h2><div class="research-box"><p>8 个阅读模块；'+str(filled)+' / '+str(total)+' 个已登记字段有值。填充率只描述当前记录，不代表项目研究完整度。</p><p>质量分：未评。专家审核：未完成。原件来源与字段证据可追溯，不据自动整理升分。</p><ul>'+''.join(assessment)+'</ul><a href="'+h(url('/api/research-document',document='data',revision=revision))+'">下载本研究版本结构化档案</a></div></section></main></div><script>'+script+'</script></html>'
